  as r(bank text, id text, options jsonb, keys jsonb, removed jsonb);

update public.assignment_answer_keys k
set accepted_answers = (k.accepted_answers - array(select jsonb_array_elements_text(r.removed))) || r.keys,
    updated_at = now()
from shared_answer_repairs r, public.assignments a, public.classes c
where k.question_id = r.id and k.assignment_id = a.id and a.class_id = c.id
  and coalesce(c.bank, 'ib') = r.bank
  and jsonb_typeof(k.accepted_answers) = 'object';

update public.assignment_questions q
set response_options = (
  select coalesce(jsonb_agg(resolved.part order by original.position), '[]'::jsonb)
  from jsonb_array_elements(q.response_options) with ordinality original(part, position)
  cross join lateral (select case
    when r.options ? (original.part ->> 'label') then r.options -> (original.part ->> 'label')
    else original.part end as part) resolved
  where resolved.part <> 'null'::jsonb
)
from shared_answer_repairs r, public.assignments a, public.classes c
where q.question_id = r.id and q.assignment_id = a.id and a.class_id = c.id
  and coalesce(c.bank, 'ib') = r.bank
  and q.response_type = 'multipart' and jsonb_typeof(q.response_options) = 'array';
commit;
